export function photoLabel(view,places=[]){if(!view)return 'Panorama Labuan';const plaza=places.find(p=>p.properties.kind==='plaza');if(plaza&&insideDataran([view.lng,view.lat]))return plaza.properties.name;const near=places.map(place=>({name:place.properties.name,d:Math.hypot((place.geometry.coordinates[0]-view.lng)*110850,(place.geometry.coordinates[1]-view.lat)*111320)})).sort((a,b)=>a.d-b.d)[0];return near&&near.d<140?near.name:'Panorama Labuan'}
